-- Curated games, embed (#9 F2): 30 PICO-8 games from the Lexaloffle BBS that play inside PlayInWeb.
-- Play loads Lexaloffle's own cart player (bbs/widget.php, the same one its "Embed" snippet uses), so we
-- host no game code. Only carts whose settings allow embedded playback were picked; carts that turn it
-- off show "do not allow embedded playback" on the BBS and were left out.
-- Covers are 16:9 images made from each cart's 128×128 label, in public/assets/curated/pico8/.
--
-- Run after 20261110200000_curated_embed_play.sql (it adds the 'embed' play mode), and after the deploy
-- that ships the covers. Safe to run twice: games that already exist under the `listed` account are skipped.
-- Picked from the BBS "Featured" carts: original games only (no demakes of other studios' games), no
-- tools or demos. Each cart was opened in PlayInWeb's sandboxed play frame on 11 Nov 2026 and booted.
-- Taglines and descriptions are our own words; titles, labels and credit come from each BBS thread.

do $$
begin
  if to_regclass('public.project_curation') is null or to_regprocedure('public.curated_owner_id()') is null then
    raise exception 'Run 20261110130000_curated_games.sql first: it creates the listed account and project_curation.';
  end if;
  if public.curated_owner_id() is null then
    raise exception 'The listed account is missing. Run 20261110130000_curated_games.sql first.';
  end if;
  if not exists (
    select 1 from pg_constraint
    where conname = 'project_curation_play_mode_check' and pg_get_constraintdef(oid) like '%embed%'
  ) then
    raise exception 'Run 20261110200000_curated_embed_play.sql first: it adds the embed play mode.';
  end if;
end;
$$;

with seed (slug, title, tagline, description, genre, release_status, play_url, cover_path, contains_ai, creator_name, creator_url, source_url) as (
  values
    ('pico-ball', 'PICO-BALL', 'Tennis, volleyball and squash in one bouncy court, starring Jelpi.', 'A mashup of tennis, volleyball, squash and wallball with one rule: two bounces on your side is a point for the other. Play solo or with a friend on one keyboard.', 'Sports', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=pico_ball', '/assets/curated/pico8/pico-ball.webp', null, 'Munchkin', 'https://www.lexaloffle.com/bbs/?uid=48557', 'https://www.lexaloffle.com/bbs/?tid=150620'),
    ('oblivion-eve', 'Oblivion Eve', 'Combo your way through a prison that rearranges itself.', 'A roguelike action platformer. Upgrade your weapons, chain combos and dig through a shifting prison with no map to free the titan locked in its depths.', 'Platformer', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=oblivion_eve', '/assets/curated/pico8/oblivion-eve.webp', null, 'SmartAlloc', 'https://www.lexaloffle.com/bbs/?uid=71437', 'https://www.lexaloffle.com/bbs/?tid=140564'),
    ('bas-birds-and-saws', 'BAS: Birds and Saws', 'Keep a little bird one jump ahead of the rising saws.', 'An endless high-score game. Saws climb from below and speed up over time, so you keep jumping, even mid-air, to stay alive. A PICO-8 remake of the creator''s own iOS game.', 'Action', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=bas', '/assets/curated/pico8/bas-birds-and-saws.webp', null, 'yokozuna', 'https://www.lexaloffle.com/bbs/?uid=83486', 'https://www.lexaloffle.com/bbs/?tid=54986'),
    ('woodworm', 'Woodworm', 'Wiggle a hungry worm through wooden puzzles.', 'A polished puzzle game about a woodworm wiggling its way through each level. Gentle at first, properly tricky by the end.', 'Puzzle', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=woodworm', '/assets/curated/pico8/woodworm.webp', null, 'spratt', 'https://www.lexaloffle.com/bbs/?uid=60255', 'https://www.lexaloffle.com/bbs/?tid=142717'),
    ('build-a-jetpack', 'Build a Jetpack', 'Collect parts from your raft and fly a little higher each time.', 'Scavenge, open the shop on your raft and upgrade a homemade jetpack until you can reach the sky. A short game with a satisfying upgrade loop.', 'Adventure', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=build_a_jetpack', '/assets/curated/pico8/build-a-jetpack.webp', null, 'Aymeri', 'https://www.lexaloffle.com/bbs/?uid=103223', 'https://www.lexaloffle.com/bbs/?tid=144726'),
    ('air-delivery', 'Air Delivery', 'The mail stopped arriving. Climb the sky islands to find out why.', 'You deliver letters between floating islands. Explore, climb and find every lost package for its recipient. First made in 48 hours for Ludum Dare 53, then expanded.', 'Platformer', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=air_delivery_1', '/assets/curated/pico8/air-delivery.webp', null, 'pianoman373', 'https://www.lexaloffle.com/bbs/?uid=73699', 'https://www.lexaloffle.com/bbs/?tid=52598'),
    ('motion-rec', 'MOTION●REC', 'Record your moves, then replay them forward or backward.', 'An action puzzle game built on one idea: record a motion, play it back, or play it in reverse to cross each stage. About ten minutes long, and later expanded on Steam.', 'Puzzle', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=motionrec', '/assets/curated/pico8/motion-rec.webp', null, 'shoma', 'https://www.lexaloffle.com/bbs/?uid=52268', 'https://www.lexaloffle.com/bbs/?tid=53392'),
    ('whiplash-taxi-co', 'Whiplash Taxi Co', 'The slower you''re there, the lower the fare.', 'Drive a 3D taxi around town, pick up passengers under the red arrows and get them to their stop as fast as possible, by any route you can find.', 'Racing', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=mot_taxi', '/assets/curated/pico8/whiplash-taxi-co.webp', null, 'Mot', 'https://www.lexaloffle.com/bbs/?uid=39676', 'https://www.lexaloffle.com/bbs/?tid=53583'),
    ('puzzles-of-the-paladin', 'Puzzles of the Paladin', '62 rooms, scarce items, and monsters to outsmart.', 'A young hero takes the trials of the Sunforged Knights. In each room, use the few items you have to defeat the monsters and reach the exit as efficiently as you can.', 'Puzzle', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=puzzlesofthepaladin', '/assets/curated/pico8/puzzles-of-the-paladin.webp', null, 'NerdyTeachers', 'https://www.lexaloffle.com/bbs/?uid=25898', 'https://www.lexaloffle.com/bbs/?tid=140488'),
    ('subsurface', 'subsurface', 'A bite-sized metroidvania under the surface.', 'Explore 40 screens, find 6 upgrades and face one boss. A complete little metroidvania you can finish in about ten minutes.', 'Platformer', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=subsurface', '/assets/curated/pico8/subsurface.webp', null, 'JulianR', 'https://www.lexaloffle.com/bbs/?uid=80516', 'https://www.lexaloffle.com/bbs/?tid=54080'),
    ('dungeon', 'DUNGEON!', 'A new dungeon every run. How deep can you get?', 'A retro platformer with randomly generated levels. Wall jump, bonk monsters, collect coins and spend them on power-ups in the gift shop.', 'Platformer', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=dungeon', '/assets/curated/pico8/dungeon.webp', null, 'deklaswas', 'https://www.lexaloffle.com/bbs/?uid=62203', 'https://www.lexaloffle.com/bbs/?tid=46206'),
    ('hot-wax', 'Hot Wax', 'Lay candle pieces and keep the flame burning.', 'You are the Wax Whisperer. Move the pieces to build long lines of candles, then keep the fire alive as long as you can for a bigger score.', 'Puzzle', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=hotwax', '/assets/curated/pico8/hot-wax.webp', null, 'lorandbehold', 'https://www.lexaloffle.com/bbs/?uid=11047', 'https://www.lexaloffle.com/bbs/?tid=141756'),
    ('lab-cat', 'Lab Cat', 'A box-pushing experiment for one curious cat, with portals.', 'Push every box onto its sensor. Portals help, and some of them ride on the boxes themselves. A clever take on the classic push puzzle.', 'Puzzle', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=lab_cat', '/assets/curated/pico8/lab-cat.webp', null, 'ooooggll', 'https://www.lexaloffle.com/bbs/?uid=57071', 'https://www.lexaloffle.com/bbs/?tid=54754'),
    ('the-heavens', 'The Heavens', 'Fly to the edge of the known universe.', 'An open-world space game. Thrust between planets, mine asteroids, colonise worlds and uncover an ancient alien race while you build a stellar empire.', 'Simulation', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=the_heavens_1', '/assets/curated/pico8/the-heavens.webp', null, 'reskob', 'https://www.lexaloffle.com/bbs/?uid=78683', 'https://www.lexaloffle.com/bbs/?tid=53946'),
    ('balloon', 'Balloon', 'Guide a fragile balloon past everything sharp.', 'A small, tightly made platformer where a balloon carries a key through rooms full of obstacles. Surprisingly good game feel once it gets going.', 'Platformer', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=balloon', '/assets/curated/pico8/balloon.webp', null, 'Lobo', 'https://www.lexaloffle.com/bbs/?uid=55954', 'https://www.lexaloffle.com/bbs/?tid=142641'),
    ('terra-nova-pinball', 'Terra Nova Pinball', 'A full pinball table on an alien world.', 'Launch, flip and ricochet around an alien table. Hit targets and finish minigames for points, with three balls per game and saved high scores.', 'Action', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=terra_nova_pinball', '/assets/curated/pico8/terra-nova-pinball.webp', null, 'xietanu', 'https://www.lexaloffle.com/bbs/?uid=66688', 'https://www.lexaloffle.com/bbs/?tid=49068'),
    ('hit8ox', 'HIT8OX', 'A fully 3D fighting game, inside PICO-8.', 'Fight the AI on three difficulty levels or a friend in versus mode across city stages. Customise your fighter''s colours and watch your stamina.', 'Fighting', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=hit8ox', '/assets/curated/pico8/hit8ox.webp', null, 'vladcom', 'https://www.lexaloffle.com/bbs/?uid=41294', 'https://www.lexaloffle.com/bbs/?tid=52278'),
    ('nemo-picross', 'NEMO', 'Comfortable picross puzzles with smooth controls.', 'A nonogram game: use the number clues to fill in the grid and reveal a picture. Easy to pick up and pleasant to control.', 'Puzzle', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=nemonemo', '/assets/curated/pico8/nemo-picross.webp', null, 'mooon', 'https://www.lexaloffle.com/bbs/?uid=61765', 'https://www.lexaloffle.com/bbs/?tid=46330'),
    ('super-hat-girl', 'Super Hat Girl!', 'Every hat gives her a new power.', 'A calm puzzle platformer. Jump through creative levels and switch hats to use new powers, all in a cute, polished package.', 'Platformer', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=super_hat_girl', '/assets/curated/pico8/super-hat-girl.webp', null, 'benvium', 'https://www.lexaloffle.com/bbs/?uid=120205', 'https://www.lexaloffle.com/bbs/?tid=148060'),
    ('top-speed', 'Top Speed!', 'Top-down kart racing for the trophy.', 'Race around top-down circuits, practise each track and fight for first place in a quick, polished arcade racer.', 'Racing', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=top_speed', '/assets/curated/pico8/top-speed.webp', null, 'benvium', 'https://www.lexaloffle.com/bbs/?uid=120205', 'https://www.lexaloffle.com/bbs/?tid=148203'),
    ('mole-mole', 'Mole Mole', 'Collect bombs and blast your way through.', 'About 25 short puzzle levels built around one action: place the bombs you have collected. Simple to learn, very hard to put down.', 'Puzzle', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=molemole', '/assets/curated/pico8/mole-mole.webp', null, 'Adam Atomic', 'https://www.lexaloffle.com/bbs/?uid=13953', 'https://www.lexaloffle.com/bbs/?tid=148484'),
    ('petal-quest', 'Petal Quest', 'A tiny adventure in a forest of secrets.', 'A game of discovery with light puzzles. Wander a small forest, talk to its residents and find what it is hiding.', 'Adventure', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=petal_quest', '/assets/curated/pico8/petal-quest.webp', null, 'noelcody', 'https://www.lexaloffle.com/bbs/?uid=110720', 'https://www.lexaloffle.com/bbs/?tid=146496'),
    ('ruby-eyes', 'Ruby Eyes', 'A little skeleton wants rubies for eyes.', 'A turn-based dungeon crawler. Climb the Necromancer''s Tower as a wee skeleton to steal the gems that will make your skull beautiful.', 'Role Playing', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=rubyeyes', '/assets/curated/pico8/ruby-eyes.webp', null, 'paperskull', 'https://www.lexaloffle.com/bbs/?uid=88208', 'https://www.lexaloffle.com/bbs/?tid=139895'),
    ('beam', 'Beam', 'A quiet, mysterious top-down puzzle adventure.', 'Explore a relaxing, pretty world and solve its puzzles. Read the signs if you get stuck. Inspired by Zelda, Myst and The Witness. Contains flashing lights.', 'Adventure', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=beam4', '/assets/curated/pico8/beam.webp', null, 'rupees', 'https://www.lexaloffle.com/bbs/?uid=80228', 'https://www.lexaloffle.com/bbs/?tid=142844'),
    ('bubblegum-spin', 'Bubblegum Spin', 'Pop gumballs before the sticky mass reaches the edge.', 'A tactical bubble shooter played at your own pace. Match three gumballs of a colour to clear them, but every few misses the mass grows.', 'Puzzle', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=bubblegum_spin', '/assets/curated/pico8/bubblegum-spin.webp', null, 'Bee_Randon', 'https://www.lexaloffle.com/bbs/?uid=70995', 'https://www.lexaloffle.com/bbs/?tid=140885'),
    ('dino-sort', 'Dino Sort', 'Sort the dinosaurs into their pens.', 'A sorting puzzle with hand-made levels, an endless mode with random puzzles, and a daily challenge everyone plays together.', 'Puzzle', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=dino_sort', '/assets/curated/pico8/dino-sort.webp', null, 'Adam Atomic', 'https://www.lexaloffle.com/bbs/?uid=13953', 'https://www.lexaloffle.com/bbs/?tid=149747'),
    ('province', 'Province', 'Grow a village and send knights to the king.', 'A small city builder. Connect buildings with roads, farm next to windmills and manage your trees to raise enough knights to prove your worth.', 'Strategy', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=province', '/assets/curated/pico8/province.webp', null, 'Perfoon', 'https://www.lexaloffle.com/bbs/?uid=123380', 'https://www.lexaloffle.com/bbs/?tid=148950'),
    ('little-eidolons', 'Little Eidolons', 'Catch, train and battle over 100 monsters.', 'An open-world RPG with grid-based, turn-based battles. Collect a team of Eidolons and protect the little wizard, because if they fall it''s game over.', 'Role Playing', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=littleeidolons_1', '/assets/curated/pico8/little-eidolons.webp', null, 'SmartAlloc', 'https://www.lexaloffle.com/bbs/?uid=71437', 'https://www.lexaloffle.com/bbs/?tid=51160'),
    ('time-for-lunch', 'Time For Lunch', 'Fly the wizard''s lunch basket home without smashing it.', 'Steer an owl carrying a basket of sandwiches through the castle. Avoid the creatures and don''t hit the walls too hard. Made for Ludum Dare 53 by PICO-8''s creator.', 'Action', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=tfl', '/assets/curated/pico8/time-for-lunch.webp', null, 'zep', 'https://www.lexaloffle.com/bbs/?uid=1', 'https://www.lexaloffle.com/bbs/?tid=52576'),
    ('sokoblox', 'Sokoblox', 'Box pushing meets block rolling.', 'A hybrid of Sokoban and Bloxorz across 15 levels. Push and roll blocks onto their goals and figure out how they move together.', 'Puzzle', 'released', 'https://www.lexaloffle.com/bbs/widget.php?pid=sokoblox', '/assets/curated/pico8/sokoblox.webp', null, 'codeAtorium', 'https://www.lexaloffle.com/bbs/?uid=73959', 'https://www.lexaloffle.com/bbs/?tid=51802')
),
new_projects as (
  insert into public.projects (
    owner_id, title, slug, tagline, description, genre, classification, kind, release_status,
    pricing_type, community, contains_ai, play_url, embeddable, cover_path, published
  )
  select
    public.curated_owner_id(), s.title, s.slug, s.tagline, s.description, s.genre, 'game', 'external', s.release_status,
    'no_payments', 'disabled', s.contains_ai::boolean, s.play_url, true, s.cover_path, true
  from seed s
  on conflict (owner_id, slug) do nothing
  returning id, slug
)
insert into public.project_curation (project_id, status, play_mode, creator_name, creator_url, source_url, license)
select p.id, 'listed', 'embed', s.creator_name, s.creator_url, s.source_url, 'Link only'
from new_projects p
join seed s on s.slug = p.slug
on conflict (project_id) do nothing;
